    [Xunit.Fact]
    public static void TestATaggedSpanIsTakenByATableWithoutRulesAndFlaggedInARuledOne() {
        emon.Port.Cells tb = emon.Port.NewCells();
        emon.Port.Cells tc = emon.Port.NewCells();
        TttTb(tb, 10000, 10000, 16000, 13000, 1, 900, 2, 2, 0, 4);
        TttTc(tc, 0, 0, 1);
        TttTc(tc, 0, 1, 1);
        TttTc(tc, 1, 0, 1);
        TttTc(tc, 1, 1, 1);
        emon.Testport.AssertEq(Table.TbTagSpan(tb, 0, tc, 0, 4, 0, 0, 1, 2), 0, "a ruled table keeps its lattice: the first row's two cells stay two");
        emon.Testport.AssertEq(emon.Port.CellsAt(tb, 24), 2, "and the table is flagged: a tagged span crosses an edge the rules close");
        emon.Testport.AssertEq(emon.Port.CellsAt(tc, 3), 1, "the cell is unchanged");
        emon.Port.CellsDrop(tb, 0);
        emon.Port.CellsDrop(tc, 0);
        TttTb(tb, 10000, 10000, 16000, 13000, 4, 700, 2, 2, 0, 4);
        TttTc(tc, 0, 0, 1);
        TttTc(tc, 0, 1, 0);
        TttTc(tc, 1, 0, 1);
        TttTc(tc, 1, 1, 1);
        emon.Testport.AssertEq(Table.TbTagSpan(tb, 0, tc, 0, 4, 0, 0, 1, 2), 1, "a whitespace table takes the tagged span over an empty cell");
        emon.Testport.AssertEq(emon.Port.CellsAt(tc, 3), 2, "the cell spans two columns");
        emon.Testport.AssertEq(emon.Port.CellsAt(tc, 16 + 12), 1, "the empty cell is absorbed");
        emon.Testport.AssertEq(emon.Port.CellsAt(tc, 6 + 0), 16000, "and the cell's box grows to cover it");
        emon.Testport.AssertEq(emon.Port.CellsAt(tb, 24), 1, "the tags shaped the table");
        emon.Port.CellsDrop(tb, 0);
        emon.Port.CellsDrop(tc, 0);
        TttTb(tb, 10000, 10000, 16000, 13000, 4, 700, 2, 2, 0, 4);
        TttTc(tc, 0, 0, 1);
        TttTc(tc, 0, 1, 1);
        TttTc(tc, 1, 0, 1);
        TttTc(tc, 1, 1, 1);
        emon.Testport.AssertEq(Table.TbTagSpan(tb, 0, tc, 0, 4, 0, 0, 1, 2), 0, "a span over a cell that has text is not taken");
        emon.Testport.AssertEq(emon.Port.CellsAt(tb, 24), 0, "and nothing is flagged: no rule closes it");
    }
    [Xunit.Fact]
    public static void TestOcrTableHintsBreakTiesAndOnlyTies() {
        emon.Port.Cells tb = emon.Port.NewCells();
        emon.Port.Cells grg = emon.Port.NewCells();
        int i = 0;
        TttTb(tb, 10000, 10000, 16000, 13000, 4, 700, 2, 2, 0, 0);
        TttTb(tb, 10100, 10000, 16000, 13000, 3, 720, 2, 2, 0, 0);
        emon.Testport.AssertEq(Table.TbTieBonus(tb, 0, 0, 2, grg), 0, "no hint, no bonus");
        while (i < 16) {
            emon.Port.CellsPush(grg, 0);
            i += 1;
        }
        emon.Port.CellsSet(grg, 0, 1);
        emon.Port.CellsSet(grg, 1, 10000);
        emon.Port.CellsSet(grg, 2, 10000);
        emon.Port.CellsSet(grg, 3, 16000);
        emon.Port.CellsSet(grg, 4, 13000);
        emon.Port.CellsSet(grg, 5, 3);
        emon.Testport.AssertEq(Table.TbHintIou(tb, 0, grg), 1000, "the hint is the first candidate's box");
        emon.Testport.AssertThat(Table.TbHintIou(tb, 1, grg) < 1000, "and only nearly the second's");
        emon.Testport.AssertEq(Table.TbTieBonus(tb, 0, 0, 2, grg), 26, "the first candidate wins the tie: a bonus over the 25 the scores may differ by");
        emon.Testport.AssertEq(Table.TbTieBonus(tb, 1, 0, 2, grg), 0, "the second does not");
        emon.Port.CellsSet(tb, Tagtable.Tbs + 6, 900);
        emon.Testport.AssertEq(Table.TbTieBonus(tb, 0, 0, 2, grg), 0, "a candidate 200 better is no tie: OCR does not override the score");
        emon.Port.CellsSet(grg, 5, 2);
        emon.Port.CellsSet(tb, Tagtable.Tbs + 6, 720);
        emon.Testport.AssertEq(Table.TbTieBonus(tb, 0, 0, 2, grg), 0, "a region that is not a table hint is not read");
    }
